function formatCategoryTokenLabel(value) {
    if (value === null || value === undefined) {
        return '';
    }
    const token = String(value).trim();
    if (!token) {
        return '';
    }
    return token
        .split(/[\s_-]+/)
        .filter(Boolean)
        .map(part => part.charAt(0).toUpperCase() + part.slice(1))
        .join(' ');
}

function formatCategoryFeeDueLabel(value) {
    if (value === null || value === undefined) {
        return '';
    }
    const normalized = String(value).trim().toLowerCase();
    if (CATEGORY_AD_FEE_DUE_LABELS.has(normalized)) {
        return CATEGORY_AD_FEE_DUE_LABELS.get(normalized);
    }
    return formatCategoryTokenLabel(value);
}

function formatCategoryFeeTypeLabel(value) {
    if (value === null || value === undefined) {
        return '';
    }
    const normalized = String(value).trim().toLowerCase();
    if (CATEGORY_AD_FEE_TYPE_LABELS.has(normalized)) {
        return CATEGORY_AD_FEE_TYPE_LABELS.get(normalized);
    }
    return formatCategoryTokenLabel(value);
}

function formatCategoryNumericValue(value) {
    if (value === null || value === undefined) {
        return '';
    }
    if (typeof value === 'number') {
        return Number.isFinite(value) ? value.toString() : '';
    }
    const trimmed = String(value).trim();
    if (!trimmed) {
        return '';
    }
    const parsed = Number.parseFloat(trimmed);
    if (Number.isFinite(parsed)) {
        return parsed.toString();
    }
    return trimmed;
}

function formatCategoryBooleanLabel(value) {
    if (value === null || value === undefined) {
        return '';
    }
    if (typeof value === 'boolean') {
        return value ? 'Yes' : 'No';
    }
    const normalized = String(value).trim().toLowerCase();
    if (!normalized) {
        return '';
    }
    if (['yes', 'true', '1', 'enabled', 'active'].includes(normalized)) {
        return 'Yes';
    }
    if (['no', 'false', '0', 'disabled', 'inactive'].includes(normalized)) {
        return 'No';
    }
    return formatCategoryTokenLabel(value);
}

function formatCategoryAuctionPeriods(entries) {
    const summary = formatAuctionPeriodsSummary(entries);
    return summary || '';
}

function normalizeMinimumBidSellerScope(value, fallback = 'no') {
    if (value === null || value === undefined) {
        return fallback;
    }
    if (typeof value === 'boolean') {
        return value ? 'yes' : 'no';
    }
    if (typeof value === 'number') {
        return Number.isFinite(value) && value !== 0 ? 'yes' : 'no';
    }
    const text = String(value).trim();
    if (!text) {
        return fallback;
    }
    const normalized = text.toLowerCase();
    if (/(individual|personal)/.test(normalized)) {
        return 'individual-only';
    }
    if (/(business|company|companies|corporate|merchant|merchants)/.test(normalized)) {
        return 'business-only';
    }
    if (normalized === '1') {
        return 'yes';
    }
    if (normalized === '0') {
        return 'no';
    }
    if (/(yes|y|true|allow|allowed|enabled|all|any|everyone)/.test(normalized)) {
        return 'yes';
    }
    if (/(no|n|false|deny|denied|disabled|none|never|not allowed|disallow)/.test(normalized)) {
        return 'no';
    }
    return fallback;
}

function formatMinimumBidSellerScopeLabel(value) {
    const normalized = normalizeMinimumBidSellerScope(value, '');
    switch (normalized) {
        case 'yes':
            return 'Yes';
        case 'no':
            return 'No';
        case 'individual-only':
            return 'Individual Accounts Only';
        case 'business-only':
            return 'Business Accounts Only';
        default:
            return normalized ? formatCategoryTokenLabel(normalized) : '';
    }
}

function formatCategoryMinimumBid(amount, sellerScope) {
    const rawAmountLabel = formatCategoryNumericValue(amount);
    const amountLabel = rawAmountLabel && rawAmountLabel !== '0' ? rawAmountLabel : '';
    const scopeLabel = formatMinimumBidSellerScopeLabel(sellerScope);
    if (amountLabel && scopeLabel) {
        return `${amountLabel} (${scopeLabel})`;
    }
    if (amountLabel) {
        return amountLabel;
    }
    return scopeLabel;
}

