function sanitizeSeedProfile(profile) {
    if (!profile || typeof profile !== 'object') {
        return null;
    }
    const sanitized = {};
    let hasValue = false;
    Object.keys(SEED_PROFILE_LIMITS).forEach(key => {
        const raw = Number(profile[key]);
        if (!Number.isFinite(raw)) {
            return;
        }
        const { min, max } = SEED_PROFILE_LIMITS[key];
        const clamped = Math.min(max, Math.max(min, Math.round(raw)));
        sanitized[key] = clamped;
        hasValue = true;
    });
    return hasValue ? sanitized : null;
}

function resolveSeedPreference(account, key, min, max) {
    if (!account || typeof account !== 'object') {
        return null;
    }
    const profile = account.seedProfile && typeof account.seedProfile === 'object'
        ? account.seedProfile
        : null;
    if (!profile || !(key in profile)) {
        return null;
    }
    const lowerBound = Number.isFinite(min) ? min : Number.NEGATIVE_INFINITY;
    const upperBound = Number.isFinite(max) ? max : Number.POSITIVE_INFINITY;
    const raw = Number(profile[key]);
    if (!Number.isFinite(raw)) {
        return null;
    }
    const clamped = Math.min(upperBound, Math.max(lowerBound, Math.round(raw)));
    profile[key] = clamped;
    return clamped;
}

function formatPointsNote(template, replacements) {
    if (typeof template !== 'string') {
        return '';
    }
    return template.replace(/\{(.*?)\}/g, (match, key) => {
        if (!key) {
            return match;
        }
        const replacement = replacements && Object.prototype.hasOwnProperty.call(replacements, key)
            ? replacements[key]
            : undefined;
        return replacement === undefined || replacement === null ? match : String(replacement);
    });
}

function generateOrderIdFromRng(rng) {
    const randomDigits = Math.floor(rng() * 900000) + 100000;
    return `ORD-${randomDigits}`;
}

function generateWalletAdIdFromRng(rng) {
    const code = Math.floor(rng() * 9000) + 1000;
    return `AD-${code}`;
}

function hashString(value) {
    const source = String(value || '');
    let hash = 0;
    for (let index = 0; index < source.length; index += 1) {
        hash = ((hash << 5) - hash + source.charCodeAt(index)) | 0;
    }
    return hash >>> 0;
}

function createDeterministicRandom(seed) {
    let state = hashString(seed) || 1;
    return function next() {
        state = (state * 1664525 + 1013904223) >>> 0;
        return state / 0x100000000;
    };
}

function pickFromArray(rng, collection) {
    const list = Array.isArray(collection) && collection.length ? collection : [''];
    const index = Math.floor(rng() * list.length) % list.length;
    return list[index];
}

